//! 🧪️ The actual read registry birth retains its Source and fixed allocation on denial and cancellation.
use semio_framework_value_control_contract::{OriginalEffectReply,OriginalEffectReplyComplete,OriginalWorkBindingIdentity,RetainedAllocationEffect,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,RetirementDemand,ValueError};
use semio_framework_value_retirement::OriginalRetirementFailure;
use semio_framework_value_read::{ReadAuthority,ReadLeaseIssue,ReadRegistryBirth};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use std::mem::size_of;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn run(bank:&mut EffectBank,d:RetirementDemand,work:u64,operation:impl for<'r> FnOnce(&mut RetainedAllocationEffect<'_>,OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>)->RetainedCloneProgress{let g=grant(d);let mut reply=None;let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,work,|effect|{let before=effect.performed_work();drop(operation(effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:reply.take().unwrap(),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native read birth unexpectedly pending")};let p=turn.result.unwrap().progress();assert_eq!(marker.unwrap_or(0),heap.0);assert_eq!(bank.take_admitted(),if turn.work==0{None}else{Some(true)});bank.post(p,g,heap);p}
#[test]fn issued_read_headers_fit_the_original_bounded_turn(){let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let maximum=law["maximumCopy"].as_u64().unwrap()as usize;assert!(ReadAuthority::<u64>::admission_demand().copy_bytes<=maximum);assert!(ReadLeaseIssue::<u64>::admission_demand().copy_bytes<=maximum)}
#[test]fn partial_registry_birth_keeps_its_original_source_and_releases_the_same_backing(){let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let chunk=law["chunk"].as_u64().unwrap()as usize;let reserve=ReadRegistryBirth::<u64>::slots_reserve_demand().unwrap();let fill=ReadRegistryBirth::<u64>::slots_fill_demand(chunk).unwrap();let discard=ReadRegistryBirth::<u64>::slots_discard_demand(chunk).unwrap();let release=ReadRegistryBirth::<u64>::slots_release_demand().unwrap();let fill_work=ReadRegistryBirth::<u64>::slots_fill_work(chunk).unwrap();let discard_work=ReadRegistryBirth::<u64>::slots_discard_work(chunk).unwrap();let identity=size_of::<Option<OriginalWorkBindingIdentity>>();let copy=2*identity+reserve.copy_bytes+fill.copy_bytes+size_of::<bool>()+discard.copy_bytes+release.copy_bytes;let stock=RetainedCloneGrant{maximum_items:7,maximum_copy_bytes:copy,maximum_capacity_bytes:reserve.capacity_bytes,maximum_release_bytes:release.release_bytes,maximum_depth:8};let mut bank=EffectBank::new(Wallet::new(stock,5+fill_work+discard_work));let mut birth=ReadRegistryBirth::<u64>::new();let body=fill.copy_bytes;let d=birth.advance_demand(body,fill_work).unwrap();assert_eq!(run(&mut bank,d,0,|e,r|birth.advance_into(body,fill_work,e,r)),RetainedCloneProgress::default());assert!(birth.terminal_is_empty());for _ in 0..3{let d=birth.advance_demand(body,fill_work).unwrap();let w=birth.advance_work_demand(body,fill_work).unwrap();run(&mut bank,d,w,|e,r|birth.advance_into(body,fill_work,e,r));}assert_eq!(birth.initialized(),(chunk,0));let mut foreign=EffectBank::new(Wallet::new(stock,5+fill_work+discard_work));let d=birth.advance_demand(body,fill_work).unwrap();let w=birth.advance_work_demand(body,fill_work).unwrap();let mut reply=None;let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||foreign.run(grant(d),w,|e|{let before=e.performed_work();let result=birth.advance_into(body,fill_work,e,OriginalEffectReply::borrow(&mut reply).unwrap());assert!(result.is_err());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:e.performed_work()-before})}));assert!(matches!(poll,RetainedWorkPoll::Complete(_)));assert_eq!(marker,None);assert_eq!(heap,(0,0));assert!(reply.is_none());assert_eq!(foreign.take_admitted(),None);assert_eq!(birth.initialized(),(chunk,0));for _ in 0..8{if birth.terminal_is_empty(){break}let d=birth.cancel_demand(body,fill_work).unwrap();let w=birth.cancel_work_demand(body,fill_work).unwrap();run(&mut bank,d,w,|e,r|birth.cancel_into(body,fill_work,e,r));}assert!(birth.terminal_is_empty());assert_eq!(bank.wallet().remaining_work(),0)}
#[test]fn full_fixed_registry_seed_is_bounded_and_cancels_both_original_backings(){type Birth=ReadRegistryBirth<u64>;let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();let capacity=law["capacity"].as_u64().unwrap()as usize;let chunk=law["chunk"].as_u64().unwrap()as usize;let slots=Birth::slots_reserve_demand().unwrap();let free=Birth::free_reserve_demand().unwrap();let fill=Birth::slots_fill_demand(chunk).unwrap();let maximum=Birth::slots_fill_work(chunk).unwrap();let free_chunk=capacity.min((fill.copy_bytes-size_of::<usize>())/size_of::<u16>()).min(((maximum-1)/4)as usize);let free_counts:Vec<_>=(0..capacity).step_by(free_chunk).map(|offset|(capacity-offset).min(free_chunk)).collect();let slot_turns=capacity/chunk;let free_copy:usize=free_counts.iter().map(|count|Birth::free_fill_demand(*count).unwrap().copy_bytes).sum();let free_work:u64=free_counts.iter().map(|count|Birth::free_fill_work(*count).unwrap()).sum();let identity=size_of::<Option<OriginalWorkBindingIdentity>>();let copy=2*identity+slots.copy_bytes+slot_turns*fill.copy_bytes+Birth::slots_publication_demand().unwrap().copy_bytes+free.copy_bytes+free_copy+Birth::free_publication_demand().unwrap().copy_bytes+Birth::registry_seed_demand().copy_bytes+size_of::<bool>()+Birth::slot_output_release_demand().copy_bytes+Birth::free_output_release_demand().copy_bytes+Birth::registry_clear_demand().copy_bytes;let work=11+slot_turns as u64*maximum+free_work;let physical=slots.capacity_bytes+free.capacity_bytes;let stock=RetainedCloneGrant{maximum_items:11+slot_turns+free_counts.len(),maximum_copy_bytes:copy,maximum_capacity_bytes:physical,maximum_release_bytes:physical,maximum_depth:8};let mut bank=EffectBank::new(Wallet::new(stock,work));let mut birth=Birth::new();assert!(Birth::registry_seed_demand().copy_bytes<=4096);for _ in 0..128{if birth.registry_prepared(){break}let d=birth.advance_demand(fill.copy_bytes,maximum).unwrap();assert!(d.copy_bytes<=4096);let w=birth.advance_work_demand(fill.copy_bytes,maximum).unwrap();run(&mut bank,d,w,|e,r|birth.advance_into(fill.copy_bytes,maximum,e,r));}assert!(birth.registry_prepared());assert!(!birth.ready());for _ in 0..16{if birth.terminal_is_empty(){break}let d=birth.cancel_demand(fill.copy_bytes,maximum).unwrap();let w=birth.cancel_work_demand(fill.copy_bytes,maximum).unwrap();run(&mut bank,d,w,|e,r|birth.cancel_into(fill.copy_bytes,maximum,e,r));}assert!(birth.terminal_is_empty());assert_eq!(bank.wallet().remaining_work(),0)}
